internal static class BreakerSelectionTests {
static int n;static void Check(bool ok,string text){n++;if(!ok)throw new Exception(text);}static void Reject(Action a,string label){bool caught=false;try{a();}catch(InvalidDataException){caught=true;}Check(caught,label);}
static Project Fixture(){var p=new Project();p.Frequency=60;p.Source.LineVoltage=400;p.Source.ShortCircuitKA=6;var b=new Board{Id="Q",Voltage=400};var c=new Circuit{Id="C",Phases=PhaseMode.Trifasico,PhaseLabel="ABC",Voltage=400,PowerKw=8*Math.Sqrt(3),PowerFactor=1,BreakerA=16,CableMm2=10,LengthM=10};c.Cable.AmpacityA=32;c.Protection.LetThroughA2s=1234;c.Protection.MagneticTripA=80;c.Protection.DisconnectSeconds=.1;c.Protection.RcdMilliA=30;b.Circuits.Add(c);p.Boards.Add(b);return p;}
static BreakerRating Rating(){return new BreakerRating{Manufacturer="Sintético QA",Reference="QA-25",VoltageV=400,FrequencyHz=60,Poles=PoleLayout.ThreePole,Metric=BreakingMetric.Icu,RatedA=25,CapacityKA=10,I2A=36.25,Source="Tabela sintética; \"A\" Ω",DataVersion="2026.10",Standard="Classificação declarada QA, não certificada",Sheet="Ensaio AC 400V 60Hz 3P"};}
static BreakerEvaluation Evaluate(Project p,BreakerRating row){return BreakerSelection.Evaluate(p,Engineering.Analyze(p).For(p.Boards[0].Circuits[0]),row,PoleLayout.ThreePole,BreakingMetric.Icu);}
[STAThread]public static int Main(){string dir=Path.Combine(Path.GetTempPath(),"breakers-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{var p=Fixture();var c=p.Boards[0].Circuits[0];var row=Rating();Check(Evaluate(p,row).Status=="Atende comparações nominais","In Iz I2 and Icu meet nominal comparison");row.CapacityKA=5;Check(Evaluate(p,row).Status=="Não atende","insufficient interruption rejected");row=Rating();row.RatedA=19;Check(Evaluate(p,row).Status=="Não atende","Ib above In rejected");row=Rating();row.RatedA=33;Check(Evaluate(p,row).Status=="Não atende","In above Iz rejected");row=Rating();row.I2A=47;Check(Evaluate(p,row).Status=="Não atende","I2 above 1.45 Iz rejected");row=Rating();row.VoltageV=230;Check(Evaluate(p,row).Status=="Não atende","different rated voltage cannot reuse capacity");row.VoltageV=415;Check(Evaluate(p,row).Status=="Não atende","higher test voltage is not extrapolated");row=Rating();row.FrequencyHz=50;Check(Evaluate(p,row).Status=="Não atende","wrong frequency rejected");row=Rating();row.Poles=PoleLayout.FourPole;Check(Evaluate(p,row).Status=="Não atende","different requested pole configuration rejected");row=Rating();row.Metric=BreakingMetric.Icn;Check(Evaluate(p,row).Status=="Não atende","Icn cannot replace requested Icu");Check(BreakerSelection.Evaluate(p,Engineering.Analyze(p).For(c),row,PoleLayout.ThreePole,BreakingMetric.Icn).Status=="Atende comparações nominais","explicit Icn selection supported");row=Rating();row.I2A=0;Check(Evaluate(p,row).Status=="Dados incompletos","missing I2 cannot get complete comparison");row=Rating();c.Cable.AmpacityA=0;Check(Evaluate(p,row).Status=="Dados incompletos","missing Iz remains pending");c.Cable.AmpacityA=32;p.Source.ShortCircuitKA=0;Check(Evaluate(p,row).Status=="Dados incompletos","missing source short remains pending");p.Source.ShortCircuitKA=6;
var library=Path.Combine(dir,"disjuntores.csv");BreakerSelection.Export(new[]{row},library);Check(BreakerSelection.Import(library).Single().Source==row.Source,"CSV quotes Unicode source roundtrip");BreakerSelection.Export(new BreakerRating[0],Path.Combine(dir,"template.csv"));Check(BreakerSelection.Import(Path.Combine(dir,"template.csv")).Count==0,"empty template supported");BreakerSelection.Export(new[]{row},library);var before=File.ReadAllBytes(library);var backup=File.ReadAllBytes(library+".bak");var invalid=Rating();invalid.Source="";Reject(delegate{BreakerSelection.Export(new[]{invalid},library);},"missing source rejected");Check(File.ReadAllBytes(library).SequenceEqual(before)&&File.ReadAllBytes(library+".bak").SequenceEqual(backup),"invalid import preserves active library and backup");Reject(delegate{BreakerSelection.Export(new[]{row,row.Copy()},library);},"duplicate condition rejected");var otherVoltage=row.Copy();otherVoltage.VoltageV=230;BreakerSelection.Export(new[]{row,otherVoltage},library);Check(BreakerSelection.Import(library).Count==2,"same product supports separate voltage condition rows");
foreach(double x in new[]{0,-1,double.NaN,double.PositiveInfinity}){invalid=Rating();invalid.CapacityKA=x;Reject(invalid.Validate,"invalid capacity rejected");}invalid=Rating();invalid.Poles=(PoleLayout)50;Reject(invalid.Validate,"unknown poles rejected");invalid=Rating();invalid.Metric=(BreakingMetric)50;Reject(invalid.Validate,"unknown metric rejected");string large=Path.Combine(dir,"large.csv");using(var stream=File.Create(large))stream.SetLength(32L*1024*1024+1);Reject(delegate{BreakerSelection.Import(large);},"oversized import rejected");
var huge=new List<BreakerRating>();string longText=new string('x',2000);for(int i=0;i<6000;i++){var x=Rating();x.Reference="BIG-"+i;x.Source=x.DataVersion=x.Sheet=longText;huge.Add(x);}before=File.ReadAllBytes(library);backup=File.ReadAllBytes(library+".bak");Reject(delegate{BreakerSelection.Export(huge,library);},"oversized export rejected");Check(File.ReadAllBytes(library).SequenceEqual(before)&&File.ReadAllBytes(library+".bak").SequenceEqual(backup)&&Directory.GetFiles(dir,"*.tmp").Length==0,"oversized export preserves library backup and removes temporary files");
var originalBreaker=c.BreakerA;row.CapacityKA=5;Reject(delegate{BreakerSelection.Apply(p,c,row,PoleLayout.ThreePole,BreakingMetric.Icu);},"bad selection cannot be applied");Check(c.BreakerA==originalBreaker&&c.Protection.BreakerSnapshot==null&&c.Protection.LetThroughA2s==1234,"rejected selection changes nothing");row=Rating();c.CurveStudy=new CurveStudyData{Downstream=ManufacturerCurve.Parse("CurrentA;MinSeconds;MaxSeconds\n10;1;2\n100;.1;.2","Curva anterior")};BreakerSelection.Apply(p,c,row,PoleLayout.ThreePole,BreakingMetric.Icu);Check(c.BreakerA==25&&c.Protection.BreakingCapacityKA==10&&c.Protection.ConventionalTripA==36.25,"selected condition applied");Check(c.Protection.LetThroughA2s==0&&c.Protection.MagneticTripA==0&&c.Protection.DisconnectSeconds==0&&c.Protection.RcdMilliA==0,"new device does not inherit old energy times magnetic or RCD ratings");Check(c.CurveStudy.Downstream==null,"new breaker clears old downstream curve");row.Source="Changed in library";Check(c.Protection.BreakerSnapshot.Rating.Source.Contains("sintética"),"snapshot independent of later library edits");Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Condições do disjuntor"&&x.Status=="OK"),"matching installed condition checked");c.Voltage=380;Check(Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Condições do disjuntor"&&x.Status=="Falha")&&Engineering.Analyze(p).Checks.Any(x=>x.Rule=="Capacidade de interrupção"&&x.Status=="Pendente"),"changed circuit voltage prevents capacity approval");c.Voltage=400;c.BreakerA=24;Reject(p.Validate,"manual nominal contradicting snapshot rejected");c.BreakerA=25;
string project=Path.Combine(dir,"project.circuito");p.Save(project);var saved=File.ReadAllText(project);Check(saved.Contains("breaker-rating-v1")&&saved.Contains("\"FileVersion\":4"),"project guarded capability format");var loaded=Project.Load(project);Check(loaded.Boards[0].Circuits[0].Protection.BreakerSnapshot.Rating.Sheet==Rating().Sheet,"snapshot survives reopen");Check(EngineeringReport.Memory(loaded,Engineering.Analyze(loaded)).Contains(Rating().Sheet),"memory contains rating source condition and sheet");string previous=Environment.GetEnvironmentVariable("CIRCUITO_QA_PREVIOUS_EXE");if(!String.IsNullOrWhiteSpace(previous)){var assembly=Assembly.LoadFile(Path.GetFullPath(previous));bool rejected=false;try{assembly.GetType("CircuitoStudio.Project").GetMethod("Load").Invoke(null,new object[]{project});}catch(TargetInvocationException ex){rejected=ex.InnerException is InvalidDataException;}Check(rejected,"actual previous executable rejects unknown breaker capability");}
var duplicate=ProjectEditing.DuplicateCircuit(p,p.Boards[0],c);Check(duplicate.Protection.BreakerSnapshot!=c.Protection.BreakerSnapshot&&duplicate.Protection.BreakerSnapshot.Rating!=c.Protection.BreakerSnapshot.Rating,"duplicate owns independent condition");p.Boards[0].Circuits.Remove(duplicate);
var mono=Fixture();var mc=mono.Boards[0].Circuits[0];mc.Phases=PhaseMode.Monofasico;mc.PhaseLabel="L1";mc.Voltage=400/Math.Sqrt(3);mc.PowerKw=2;var mr=Rating();mr.Poles=PoleLayout.OnePoleNeutral;mr.VoltageV=mc.Voltage;Check(BreakerSelection.Evaluate(mono,Engineering.Analyze(mono).For(mc),mr,PoleLayout.OnePoleNeutral,BreakingMetric.Icu).Status=="Atende comparações nominais","phase neutral two switched one protected topology");mr.Poles=PoleLayout.TwoPole;Check(BreakerSelection.Evaluate(mono,Engineering.Analyze(mono).For(mc),mr,PoleLayout.TwoPole,BreakingMetric.Icu).Status=="Não atende","phase phase poles cannot be silently interpreted phase neutral");mc.Voltage=400;mr.VoltageV=400;Check(BreakerSelection.Evaluate(mono,Engineering.Analyze(mono).For(mc),mr,PoleLayout.TwoPole,BreakingMetric.Icu).Status=="Atende comparações nominais","two phase-phase protected poles supported");
string artifacts=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"referencias-disjuntores");Directory.CreateDirectory(artifacts);p.Save(Path.Combine(artifacts,"origem.circuito"));var all=new List<BreakerRating>{Rating(),otherVoltage};var insufficient=Rating();insufficient.Reference="QA-25-5kA";insufficient.CapacityKA=5;all.Add(insufficient);BreakerSelection.Export(all,Path.Combine(artifacts,"tabela.csv"));File.WriteAllText(Path.Combine(artifacts,"comparacao.txt"),Evaluate(p,Rating()).Detail);
using(var form=new BreakerSelectionForm(p,c,Path.Combine(artifacts,"tabela.csv"))){form.CreateControl();var checkbox=(CheckBox)typeof(BreakerSelectionForm).GetField("compatibleOnly",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);checkbox.Checked=true;var grid=(DataGridView)typeof(BreakerSelectionForm).GetField("grid",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(form);Check(grid.Rows.Count==1,"filter retains only matching poles voltage and current capacity");Check(!form.Changed,"opening filter does not change project");if(Environment.GetEnvironmentVariable("CIRCUITO_QA_VISUAL")=="1"){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(10,10);form.Show();Application.DoEvents();using(var bitmap=new Bitmap(form.ClientSize.Width,form.ClientSize.Height)){using(var graphics=Graphics.FromImage(bitmap))graphics.CopyFromScreen(form.PointToScreen(Point.Empty),Point.Empty,form.ClientSize);bitmap.Save(Path.Combine(artifacts,"disjuntores.png"));}form.Hide();}}
Console.WriteLine("PASS: "+n+" breaker-selection assertions");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{Directory.Delete(dir,true);}}
}
